  );
}

function NavBar({ page, setPage, isPaid, setIsPaid, mobileOpen, setMobileOpen }) {
  const items = [
    { key: "home", label: "Home", icon: HomeIcon },
    { key: "courses", label: "Courses", icon: BookOpen },
