  const [activeCourseId, setActiveCourseId] = useState(COURSES[0].id);
  const [mobileOpen, setMobileOpen] = useState(false);

  return (
    <div className="min-h-screen bg-gray-50 font-sans">
      <NavBar
        page={page}
        setPage={setPage}
        isPaid={isPaid}
        setIsPaid={setIsPaid}
        mobileOpen={mobileOpen}
